def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    def rand_ops(q, lo, hi, w):
        ops, cnt = [], 0
        for _ in range(q):
            if cnt == 0 or rng.random() < w:
                ops.append('push %d' % rng.randint(lo, hi))
                cnt += 1
            else:
                op = rng.choice(['pop', 'top', 'popMin', 'popMax'])
                ops.append(op)
                if op != 'top':
                    cnt -= 1
        if all(o.startswith('push') for o in ops):
            ops.append('top')
        return ops

    tests = [
        fmt(['push 1', 'top']), fmt(['push 5', 'popMin']), fmt(['push 5', 'popMax']),
        fmt(['push 3', 'push 3', 'popMax', 'popMin']),
        fmt(['push 1', 'push 2', 'push 3', 'popMin', 'popMax', 'pop']),
        fmt(['push 3', 'push 2', 'push 1', 'popMax', 'top', 'popMin', 'top']),
        fmt(['push -7', 'push 0', 'push -7', 'popMin', 'popMin', 'top']),
    ]
    for q in (5, 8, 12, 16, 20, 25, 30):
        for w in (0.5, 0.7):
            tests.append(fmt(rand_ops(q, -5, 5, w)))
    tests.append(fmt(rand_ops(30, -10**9, 10**9, 0.6)))

    ops = ['push %d' % rng.randint(-10**9, 10**9) for _ in range(50000)]
    cyc = ['popMin', 'popMax', 'top', 'pop']
    ops += [cyc[i % 4] for i in range(50000)]
    tests.append(fmt(ops))
    tests.append(fmt(rand_ops(100000, -10**9, 10**9, 0.6)))
    tests.append(fmt(rand_ops(100000, 1, 5, 0.55)))
    ops = ['push %d' % i for i in range(60000)]
    ops += ['popMin' if i % 2 == 0 else 'popMax' for i in range(40000)]
    tests.append(fmt(ops))
    return tests

